:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --accent: #0f3460;
  --highlight: #e94560;
  --button-bg: #0f3460;
  --button-hover: #1a4a7a;
  --button-active: #0a2a4a;
  --focus-ring: #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.meter-card {
  background: var(--card-bg);
  border: 4px solid var(--highlight);
  border-radius: 12px;
  padding: 24px 20px;
  max-width: 400px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  text-align: center;
}

h1 {
  font-size: 1.4rem;
  margin-bottom: 20px;
  color: var(--highlight);
  letter-spacing: 1px;
  text-transform: uppercase;
}

.display {
  background: #0a0a1a;
  border: 3px solid var(--accent);
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 12px;
}

.time-display {
  font-size: 3rem;
  font-weight: bold;
  font-family: 'Courier New', monospace;
  color: #00ff88;
  line-height: 1.2;
}

.price-display {
  font-size: 1.6rem;
  font-family: 'Courier New', monospace;
  color: #ffcc00;
  margin-top: 4px;
}

.rate {
  font-size: 0.9rem;
  color: #888;
  margin-bottom: 20px;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 12px 18px;
  border: 3px solid var(--highlight);
  border-radius: 8px;
  background: var(--button-bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  min-width: 100px;
}

.btn:hover {
  background: var(--button-hover);
}

.btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.btn:active {
  background: var(--button-active);
  transform: scale(0.96);
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
}

.btn.clear {
  border-color: #888;
}

.max-note {
  font-size: 0.8rem;
  color: #666;
  margin-top: 16px;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .meter-card {
    padding: 18px 14px;
  }
  .time-display {
    font-size: 2.4rem;
  }
  .btn {
    min-width: 80px;
    padding: 10px 14px;
    font-size: 0.9rem;
  }
}

(function () {
  const MAX_MINUTES = 180;
  const RATE_PER_HOUR = 2.00;

  const timeDisplay = document.getElementById('timeDisplay');
  const priceDisplay = document.getElementById('priceDisplay');
  const add15 = document.getElementById('add15');
  const add60 = document.getElementById('add60');
  const clearBtn = document.getElementById('clear');

  let totalMinutes = 0;

  function formatTime(minutes) {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return h + ':' + String(m).padStart(2, '0');
  }

  function formatPrice(minutes) {
    const price = (minutes / 60) * RATE_PER_HOUR;
    return '$' + price.toFixed(2);
  }

  function updateDisplay() {
    timeDisplay.textContent = formatTime(totalMinutes);
    priceDisplay.textContent = formatPrice(totalMinutes);
    const atMax = totalMinutes >= MAX_MINUTES;
    add15.disabled = atMax;
    add60.disabled = atMax;
  }

  function addMinutes(amount) {
    totalMinutes = Math.min(totalMinutes + amount, MAX_MINUTES);
    updateDisplay();
  }

  add15.addEventListener('click', function () {
    addMinutes(15);
  });

  add60.addEventListener('click', function () {
    addMinutes(60);
  });

  clearBtn.addEventListener('click', function () {
    totalMinutes = 0;
    updateDisplay();
  });

  updateDisplay();
})();
